const listInboxConversations = `-- name: ListInboxConversations :many
SELECT id, protocol, status, version, controller, controller_epoch, assignee_id,
       contact_id, cycle_number, summary, last_customer_message_at, waiting_since, created_at
FROM conversations
WHERE tenant_id = $1
  AND tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid
  AND inbox_id = $2
  AND ($3::uuid[] IS NULL OR id = ANY($3::uuid[]))
ORDER BY created_at, id
`

type ListInboxConversationsParams struct {
	TenantID      uuid.UUID
	InboxID       *uuid.UUID
	AuthorizedIds []uuid.UUID
}

type ListInboxConversationsRow struct {
	ID                    uuid.UUID
	Protocol              *string
	Status                string
	Version               int64
	Controller            string
	ControllerEpoch       int64
	AssigneeID            *uuid.UUID
	ContactID             *uuid.UUID
	CycleNumber           int32
	Summary               string
	LastCustomerMessageAt pgtype.Timestamptz
	WaitingSince          pgtype.Timestamptz
	CreatedAt             pgtype.Timestamptz
}

func (q *Queries) ListInboxConversations(ctx context.Context, arg ListInboxConversationsParams) ([]ListInboxConversationsRow, error) {
	rows, err := q.db.Query(ctx, listInboxConversations, arg.TenantID, arg.InboxID, arg.AuthorizedIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListInboxConversationsRow
	for rows.Next() {
		var i ListInboxConversationsRow
		if err := rows.Scan(
			&i.ID,
			&i.Protocol,
			&i.Status,
			&i.Version,
			&i.Controller,
			&i.ControllerEpoch,
			&i.AssigneeID,
			&i.ContactID,
			&i.CycleNumber,
			&i.Summary,
			&i.LastCustomerMessageAt,
			&i.WaitingSince,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

